CREATE TABLE "Organization" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"employeeCount" INTEGER NOT NULL DEFAULT 12,"notes" TEXT NOT NULL DEFAULT 'Оқу мақсатындағы модельдік ұйым',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Organization_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Asset" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"category" TEXT NOT NULL,"owner" TEXT NOT NULL,"criticality" INTEGER NOT NULL DEFAULT 3,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Asset_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Threat" ("id" TEXT NOT NULL,"assetId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,CONSTRAINT "Threat_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Vulnerability" ("id" TEXT NOT NULL,"threatId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,CONSTRAINT "Vulnerability_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RiskAssessment" ("id" TEXT NOT NULL,"assetId" TEXT NOT NULL,"threatId" TEXT NOT NULL,"vulnerabilityId" TEXT NOT NULL,"likelihood" INTEGER NOT NULL,"impact" INTEGER NOT NULL,"score" INTEGER NOT NULL,"severity" TEXT NOT NULL,"consequence" TEXT NOT NULL,"justification" TEXT NOT NULL,"mitigation" TEXT NOT NULL,"isSimulated" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "RiskAssessment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "RiskAssessmentHistory" ("id" TEXT NOT NULL,"assessmentId" TEXT NOT NULL,"likelihood" INTEGER NOT NULL,"impact" INTEGER NOT NULL,"score" INTEGER NOT NULL,"severity" TEXT NOT NULL,"note" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "RiskAssessmentHistory_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityControl" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"name" TEXT NOT NULL,"description" TEXT NOT NULL,"purpose" TEXT NOT NULL,"instructions" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'NOT_STARTED',"priority" TEXT NOT NULL DEFAULT 'MEDIUM',"responsible" TEXT NOT NULL,"completedAt" TIMESTAMP(3),"verificationNotes" TEXT NOT NULL DEFAULT '',CONSTRAINT "SecurityControl_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AssetSecurityControl" ("assetId" TEXT NOT NULL,"controlId" TEXT NOT NULL,CONSTRAINT "AssetSecurityControl_pkey" PRIMARY KEY ("assetId","controlId"));
CREATE TABLE "Recommendation" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"riskId" TEXT,"title" TEXT NOT NULL,"description" TEXT NOT NULL,"priority" TEXT NOT NULL,"steps" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"responsible" TEXT NOT NULL,"expectedBenefit" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Recommendation_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityPolicy" ("id" TEXT NOT NULL,"organizationId" TEXT NOT NULL,"title" TEXT NOT NULL,"detail" TEXT NOT NULL,"example" TEXT NOT NULL,"position" INTEGER NOT NULL,CONSTRAINT "SecurityPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PolicyAcknowledgement" ("id" TEXT NOT NULL,"policyId" TEXT NOT NULL,"employee" TEXT NOT NULL,"acknowledgedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "PolicyAcknowledgement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ActivityLog" ("id" TEXT NOT NULL,"action" TEXT NOT NULL,"entity" TEXT NOT NULL,"entityId" TEXT NOT NULL,"details" TEXT NOT NULL DEFAULT '',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ActivityLog_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Organization_name_key" ON "Organization"("name"); CREATE INDEX "Asset_organizationId_category_idx" ON "Asset"("organizationId","category"); CREATE INDEX "Threat_assetId_idx" ON "Threat"("assetId"); CREATE INDEX "Vulnerability_threatId_idx" ON "Vulnerability"("threatId"); CREATE INDEX "RiskAssessment_severity_score_idx" ON "RiskAssessment"("severity","score"); CREATE UNIQUE INDEX "SecurityControl_organizationId_name_key" ON "SecurityControl"("organizationId","name"); CREATE INDEX "Recommendation_org_idx" ON "Recommendation"("organizationId"); CREATE UNIQUE INDEX "SecurityPolicy_organizationId_position_key" ON "SecurityPolicy"("organizationId","position"); CREATE UNIQUE INDEX "PolicyAcknowledgement_policyId_employee_key" ON "PolicyAcknowledgement"("policyId","employee"); CREATE INDEX "ActivityLog_createdAt_idx" ON "ActivityLog"("createdAt");
ALTER TABLE "Asset" ADD CONSTRAINT "Asset_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Threat" ADD CONSTRAINT "Threat_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Vulnerability" ADD CONSTRAINT "Vulnerability_threatId_fkey" FOREIGN KEY ("threatId") REFERENCES "Threat"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RiskAssessment" ADD CONSTRAINT "RiskAssessment_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RiskAssessment" ADD CONSTRAINT "RiskAssessment_threatId_fkey" FOREIGN KEY ("threatId") REFERENCES "Threat"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RiskAssessment" ADD CONSTRAINT "RiskAssessment_vulnerabilityId_fkey" FOREIGN KEY ("vulnerabilityId") REFERENCES "Vulnerability"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "RiskAssessmentHistory" ADD CONSTRAINT "RiskAssessmentHistory_assessmentId_fkey" FOREIGN KEY ("assessmentId") REFERENCES "RiskAssessment"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "SecurityControl" ADD CONSTRAINT "SecurityControl_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AssetSecurityControl" ADD CONSTRAINT "AssetSecurityControl_assetId_fkey" FOREIGN KEY ("assetId") REFERENCES "Asset"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "AssetSecurityControl" ADD CONSTRAINT "AssetSecurityControl_controlId_fkey" FOREIGN KEY ("controlId") REFERENCES "SecurityControl"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Recommendation" ADD CONSTRAINT "Recommendation_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "Recommendation" ADD CONSTRAINT "Recommendation_riskId_fkey" FOREIGN KEY ("riskId") REFERENCES "RiskAssessment"("id") ON DELETE SET NULL ON UPDATE CASCADE; ALTER TABLE "SecurityPolicy" ADD CONSTRAINT "SecurityPolicy_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE CASCADE ON UPDATE CASCADE; ALTER TABLE "PolicyAcknowledgement" ADD CONSTRAINT "PolicyAcknowledgement_policyId_fkey" FOREIGN KEY ("policyId") REFERENCES "SecurityPolicy"("id") ON DELETE CASCADE ON UPDATE CASCADE;
